import hmac
import hashlib
import json
import base64
import time
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

SECRET_KEY = os.environ.get('JWT_SECRET', os.urandom(32).hex())
ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']

def base64url_encode(data):
    if isinstance(data, str):
        data = data.encode('utf-8')
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def base64url_decode(data):
    if isinstance(data, str):
        data = data.encode('utf-8')
    padding = 4 - len(data) % 4
    if padding != 4:
        data += b'=' * padding
    return base64.urlsafe_b64decode(data)

def get_hash_algorithm(alg_name):
    algorithms = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    return algorithms.get(alg_name)

def create_token(payload, secret=SECRET_KEY, algorithm='HS256'):
    header = {'alg': algorithm, 'typ': 'JWT'}
    header_encoded = base64url_encode(json.dumps(header, separators=(',', ':')))
    payload_encoded = base64url_encode(json.dumps(payload, separators=(',', ':')))
    signing_input = header_encoded + b'.' + payload_encoded
    hash_func = get_hash_algorithm(algorithm)
    signature = hmac.new(secret.encode('utf-8') if isinstance(secret, str) else secret, signing_input, hash_func).digest()
    signature_encoded = base64url_encode(signature)
    return (signing_input + b'.' + signature_encoded).decode('utf-8')

def decode_header(token):
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError('Invalid token format')
    header_data = base64url_decode(parts[0])
    return json.loads(header_data)

def verify_token(token, secret=SECRET_KEY):
    """Verify a JWT token and return the payload if valid."""
    parts = token.split('.')
    if len(parts) != 3:
        return None

    try:
        header = json.loads(base64url_decode(parts[0]))
        payload = json.loads(base64url_decode(parts[1]))
        signature = base64url_decode(parts[2])
    except (json.JSONDecodeError, Exception):
        return None

    # Validate algorithm - must be in allowlist
    alg = header.get('alg', '')
    if alg not in ALLOWED_ALGORITHMS:
        return None

    # Check expiration - validate that 'exp' is a numeric value to avoid
    # unhandled type errors (potential DoS) from malformed tokens.
    if 'exp' in payload:
        exp = payload['exp']
        if not isinstance(exp, (int, float)) or isinstance(exp, bool):
            return None
        if time.time() > exp:
            return None

    # Compute expected signature
    signing_input = (parts[0] + '.' + parts[1]).encode('utf-8')
    hash_func = get_hash_algorithm(alg)
    expected_signature = hmac.new(
        secret.encode('utf-8') if isinstance(secret, str) else secret,
        signing_input, hash_func
    ).digest()

    # Verify signature using constant-time comparison
    if hmac.compare_digest(signature, expected_signature):
        return payload
    return None

def get_user_permissions(payload):
    """Extract user permissions from token payload."""
    role = payload.get('role', 'viewer')
    permissions = {
        'admin': ['read', 'write', 'delete', 'manage_users'],
        'editor': ['read', 'write'],
        'viewer': ['read']
    }
    return permissions.get(role, ['read'])

class TokenAuthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path

        if path == '/public':
            self.send_json(200, {'message': 'Public endpoint'})
            return

        # Extract token from Authorization header
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            self.send_json(401, {'error': 'Missing or invalid authorization'})
            return

        token = auth_header[7:]
        payload = verify_token(token)

        if payload is None:
            self.send_json(401, {'error': 'Invalid or expired token'})
            return

        if path == '/profile':
            self.send_json(200, {'user': payload.get('sub'), 'role': payload.get('role')})
        elif path == '/admin':
            perms = get_user_permissions(payload)
            if 'manage_users' in perms:
                self.send_json(200, {'message': 'Admin access granted', 'users': ['alice', 'bob']})
            else:
                self.send_json(403, {'error': 'Insufficient permissions'})
        else:
            self.send_json(404, {'error': 'Not found'})

    def send_json(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode('utf-8'))

    def log_message(self, format, *args):
        pass

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), TokenAuthHandler)
    print('Server running on port 8080')
    server.serve_forever()
